reference_solution:
def shiftingLetters(s, shifts):
    n = len(s)
    diff = [0] * (n + 1)
    for a, b, d in shifts:
        v = 1 if d == 1 else -1
        diff[a] += v
        diff[b + 1] -= v
    out, cur = [], 0
    for i, ch in enumerate(s):
        cur += diff[i]
        out.append(chr((ord(ch) - 97 + cur) % 26 + 97))
    return "".join(out)

brute_force_solution:
def shiftingLetters(s, shifts):
    vals = [ord(c) - 97 for c in s]
    for a, b, d in shifts:
        for i in range(a, b + 1):
            vals[i] = (vals[i] + (1 if d == 1 else -1)) % 26
    return "".join(chr(v + 97) for v in vals)

